// One row per ranking keyword (the Actor nests them in topKeywords). Sites without data are skipped.
const minVolume = Number($('Settings').first().json.minSearchVolume) || 0;
const date = new Date().toISOString().slice(0, 10);
const out = [];
for (const { json: d } of $input.all()) {
  if (d.found === false) continue;
  for (const k of d.topKeywords || []) {
    if ((k.searchVolume ?? 0) < minVolume) continue;
    out.push({ json: {
      date, domain: d.domain, keyword: k.keyword, position: k.position, url: k.url,
      estimatedTraffic: k.estimatedTraffic == null ? null : Math.round(k.estimatedTraffic),
      searchVolume: k.searchVolume ?? null, cpcUsd: k.cpcUsd ?? null,
      keywordDifficulty: k.keywordDifficulty ?? null, searchIntent: k.searchIntent ?? null, country: d.country,
    } });
  }
}
return out;
